import { Check, GitBranch, Pin, Sparkles } from '../icons'
import { useState } from 'react'
import { NavLink, Navigate, useNavigate, useParams } from 'react-router-dom'
import { useMemory } from '../state/MemoryContext'
import screen from './Screen.module.css'
import styles from './MemoryPage.module.css'
import { getClusterPoint } from './clusterLayout'

const validLenses = ['half-life', 'constellation', 'manual']

export function MemoryPage() {
  const { lens } = useParams()
  if (!lens || !validLenses.includes(lens)) return <Navigate to="/memory/half-life" replace />
  return <section className={screen.screen}><div className={screen.inner}>
    <div className={screen.topRow}><div><span className={screen.eyebrow}>MEMORY LENS</span><p className={screen.description}>같은 기억을 시간, 관계, 문장의 세 가지 관점으로 읽습니다.</p></div><nav className={screen.tabs} aria-label="기억 렌즈"><NavLink to="/memory/half-life">Half-life</NavLink><NavLink to="/memory/constellation">Constellation</NavLink><NavLink to="/memory/manual">Manual</NavLink></nav></div>
    {lens === 'half-life' && <HalfLife />}{lens === 'constellation' && <Constellation />}{lens === 'manual' && <Manual />}
  </div></section>
}

function HalfLife() {
  const { workspace, setPinned } = useMemory()
  const navigate = useNavigate()
  const [kept, setKept] = useState(false)
  const buckets = ['now', '30d', '90d', '1y', 'archive'] as const
  const labels = ['NOW', '30D', '90D', '1Y', 'ARCHIVE']
  return <div className={styles.halfLife}>
    <div className={styles.lensHeading}><div><span>MEMORY HALF-LIFE</span><h1>612개 중 어떤 것이 식어가고 있는가</h1><p>기억은 지우는 게 아니라 시간이 지나면 옅어집니다. 붙잡고 싶은 것만 핀을 꽂으세요.</p></div><div className={styles.archiveCount}><b>18</b><span>7일 내 자동 보관 예정</span></div></div>
    <div className={styles.timelineHead}><span />{labels.map((label) => <b key={label}>{label}</b>)}</div>
    <div className={styles.timelineLine} />
    <div className={styles.memoryGrid}>
      {(['코딩','일','취향','개인'] as const).map((category) => <div className={styles.memoryRow} key={category}><strong>{category}</strong>{buckets.map((bucket) => <div key={bucket} className={styles.bucket}>{workspace.memories.filter((item) => item.category === category && item.ageBucket === bucket).map((memory) => <button key={memory.id} className={`${styles.memoryChip} ${styles[memory.state]} ${memory.pinned ? styles.pinned : ''}`} aria-label={`${memory.text} 고정`} aria-pressed={memory.pinned} onClick={() => void setPinned(memory.id, !memory.pinned)} style={{ '--strength': memory.strength } as React.CSSProperties}><span>{memory.text}</span>{memory.pinned && <Pin size={10} fill="currentColor" />}</button>)}</div>)}</div>)}
    </div>
    <div className={styles.legend}><span><i className={styles.legendStrong} />핀으로 고정됨 · 식지 않음</span><span><i className={styles.legendFading} />옅어지는 중</span><span><i className={styles.legendArchive} />곧 보관</span>{kept && <span className={styles.resolved}><Check size={13} />18개 유지됨</span>}<div /><button className={screen.button} onClick={() => setKept(true)}>보관 예정 18개 그대로 두기</button><button className={screen.buttonGhost} onClick={() => navigate('/changes', { state: { openCleanup: true } })}>하나씩 보기</button></div>
  </div>
}

function Constellation() {
  const { workspace, resolveTension } = useMemory()
  const tension = workspace.tensions[0]
  return <div className={styles.constellation}>
    <div className={styles.sky}>
      <div className={styles.skyTitle}><span>CONSTELLATION</span><h1>당신은 네 개의 덩어리로<br />이루어져 있습니다</h1></div>
      <Cluster className={styles.making} name="MAKING" count="148" words={['속도 우선','AI 코딩 도구','MVP 이틀','해커톤 몰입']} />
      <Cluster className={styles.craft} name="CRAFT" count="96" words={['완성도 타협 안 함','여백 많은 UI','정보 밀도 낮게']} />
      <Cluster className={styles.taste} name="TASTE" count="52" words={['파스텔 거부','다크 모드','디카페인']} />
      <Cluster className={styles.fadingCluster} name="FADING" count="31" words={['휴학 고민','B2C 창업']} />
      <svg className={styles.tensionLine} viewBox="0 0 310 70" aria-hidden="true"><path d="M4 48 C 86 12, 212 75, 306 18" /><circle cx="4" cy="48" r="3" /><circle cx="306" cy="18" r="3" /></svg><span className={styles.tensionTag}>팽팽함 · 조건 필요</span>
      <p className={styles.skyNote}>별의 크기는 그 기억이 답변에 실제로 쓰인 횟수입니다. 덩어리를 누르면 안쪽 기억이 펼쳐집니다.</p>
    </div>
    <aside className={styles.tensionPanel}><span className={screen.eyebrow}>SELECTED TENSION</span><h2>두 별이 서로를<br />밀어내고 있습니다</h2><div className={styles.tensionPair}><p>{tension.left}</p><GitBranch size={15} /><p>{tension.right}</p></div><span className={styles.ruleLabel}>AI가 본 규칙</span><div className={styles.rules}>{tension.rules.map((rule) => <div key={rule.context}><span>{rule.context}</span><i /><b>{rule.priority}</b></div>)}</div><div className={styles.tensionActions}>{tension.status === 'resolved' ? <span className={styles.resolved}><Check size={14} /> 조건 저장됨</span> : <><button className={screen.button} onClick={() => void resolveTension(tension.id, 'conditional')}>조건부 기억으로 분리</button><button className={screen.buttonGhost} onClick={() => void resolveTension(tension.id, 'keep-one')}>한쪽만 남기기</button></>}</div></aside>
  </div>
}

function Cluster({ className, name, count, words }: { className: string; name: string; count: string; words: string[] }) {
  return <div className={`${styles.cluster} ${className}`}><div className={styles.clusterHalo} />{words.map((word,index) => { const point = getClusterPoint(index); return <div key={word} className={styles.star} data-side={point.side} style={{ '--x': point.x, '--y': point.y, '--size': `${point.size}px` } as React.CSSProperties}><i /><span>{word}</span></div> })}<b>{name} · {count}</b></div>
}

function Manual() {
  const { workspace } = useMemory()
  const [open, setOpen] = useState('work-style')
  return <div className={styles.manualWrap}>
    <aside className={styles.marginNotes}><span>3주 전 고쳐 씀</span><p>“대체로”가<br />“거의 항상”으로</p><span className={styles.reviewNote}>검토 대기</span><p>이 문단은 8개월째<br />그대로입니다</p></aside>
    <article className={styles.manual}><header><span>A DOCUMENT ABOUT YOU · v.108</span><h1>제가 지금 알고 있는 당신</h1><p>612개의 기억을 문장 아홉 개로 줄여 썼습니다. 틀린 문장을 눌러 고쳐 주세요.</p></header>{workspace.manual.map((section) => <section key={section.id} className={section.review ? styles.manualReview : ''}><button aria-label={`${section.eyebrow} 근거 보기`} onClick={() => setOpen(open === section.id ? '' : section.id)}><span>{section.eyebrow}</span><p>{section.text}</p>{section.review && <em>이 문단 다시 쓰기</em>}</button>{open === section.id && <div className={styles.manualEvidence}><span><Sparkles size={11} /> 이렇게 판단한 근거</span>{section.evidence.map((item) => <p key={item}>{item}</p>)}</div>}</section>)}</article>
  </div>
}

