@media (max-height: 760px) {
  .halfLife { margin-top: 18px; }
  .lensHeading h1,
  .skyTitle h1 { font-size: 30px; }
  .memoryChip { min-height: 46px; }
  .manual { padding-top: 32px; }
  .manual > section > button { padding: 16px 0; }
  .constellation { height: 560px; }
}

