import { demoWorkspace } from './demoWorkspace'
import type {
  AccessRule,
  ChangeResolution,
  CorrectionScope,
  MemoryCategory,
  MemoryChange,
  MemoryCorrection,
  MemoryItem,
  MemoryRepository,
  MemoryTension,
  MemoryWorkspace,
  TensionResolution,
} from '../domain/memory'

const cloneWorkspace = () => structuredClone(demoWorkspace)

export class MockMemoryRepository implements MemoryRepository {
  private workspace = cloneWorkspace()

  async loadWorkspace(): Promise<MemoryWorkspace> {
    return structuredClone(this.workspace)
  }

  async resolveChange(id: string, _action: ChangeResolution): Promise<MemoryChange> {
    const change = this.workspace.changes.find((item) => item.id === id)
    if (!change) throw new Error(`Unknown change: ${id}`)
    change.status = 'resolved'
    return structuredClone(change)
  }

  async setPinned(id: string, pinned: boolean): Promise<MemoryItem> {
    const memory = this.workspace.memories.find((item) => item.id === id)
    if (!memory) throw new Error(`Unknown memory: ${id}`)
    memory.pinned = pinned
    return structuredClone(memory)
  }

  async resolveTension(id: string, action: TensionResolution): Promise<MemoryTension> {
    const tension = this.workspace.tensions.find((item) => item.id === id)
    if (!tension) throw new Error(`Unknown tension: ${id}`)
    tension.status = 'resolved'
    tension.resolution = action
    return structuredClone(tension)
  }

  async applyCorrection(id: string, scope: CorrectionScope): Promise<MemoryCorrection> {
    const correction = this.workspace.correction
    if (correction.id !== id) throw new Error(`Unknown correction: ${id}`)
    correction.scope = scope
    correction.status = scope === 'ignore' ? 'ignored' : 'applied'
    return structuredClone(correction)
  }

  async updateAccess(appId: string, category: MemoryCategory, enabled: boolean): Promise<AccessRule> {
    const rule = this.workspace.accessRules.find((item) => item.appId === appId && item.category === category)
    if (!rule) throw new Error(`Unknown access rule: ${appId}/${category}`)
    rule.enabled = enabled
    return structuredClone(rule)
  }

  async resetDemo(): Promise<MemoryWorkspace> {
    this.workspace = cloneWorkspace()
    return this.loadWorkspace()
  }
}

