export type MemoryCategory = '코딩' | '일' | '취향' | '개인'
export type MemoryState = 'strong' | 'fading' | 'review' | 'archived'
export type ChangeResolution = 'accept' | 'reject' | 'archive' | 'keep'
export type TensionResolution = 'conditional' | 'keep-one'
export type CorrectionScope = 'global' | 'conversation' | 'ignore'

export interface MemoryItem {
  id: string
  text: string
  category: MemoryCategory
  ageBucket: 'now' | '30d' | '90d' | '1y' | 'archive'
  ageLabel: string
  strength: number
  usageCount: number
  pinned: boolean
  state: MemoryState
}

export interface MemoryChange {
  id: string
  kind: 'changed' | 'fading' | 'duplicate' | 'contradiction'
  meta: string
  title: string
  description: string
  confidence: number
  status: 'pending' | 'resolved'
  before?: string
  after?: string
  evidence: string[]
}

export interface MemoryTension {
  id: string
  left: string
  right: string
  status: 'pending' | 'resolved'
  resolution?: TensionResolution
  rules: Array<{ context: string; priority: string }>
}

export interface ManualSection {
  id: string
  eyebrow: string
  text: string
  changedPhrase?: string
  evidence: string[]
  review?: boolean
}

export interface OrbitQuestion {
  id: string
  question: string
  answer: string
  answerCards: [string, string, string]
  meta: string
}

export interface MemoryCorrection {
  id: string
  before: string
  after: string
  status: 'pending' | 'applied' | 'ignored'
  scope?: CorrectionScope
}

export interface AccessRule {
  appId: string
  appName: string
  category: MemoryCategory
  enabled: boolean
}

export interface MemoryWorkspace {
  memoryCount: number
  week: { strengthened: number; archived: number; merged: number; pending: number }
  memories: MemoryItem[]
  changes: MemoryChange[]
  tensions: MemoryTension[]
  manual: ManualSection[]
  orbitQuestions: OrbitQuestion[]
  correction: MemoryCorrection
  accessRules: AccessRule[]
}

export interface MemoryRepository {
  loadWorkspace(): Promise<MemoryWorkspace>
  resolveChange(id: string, action: ChangeResolution): Promise<MemoryChange>
  setPinned(id: string, pinned: boolean): Promise<MemoryItem>
  resolveTension(id: string, action: TensionResolution): Promise<MemoryTension>
  applyCorrection(id: string, scope: CorrectionScope): Promise<MemoryCorrection>
  updateAccess(appId: string, category: MemoryCategory, enabled: boolean): Promise<AccessRule>
  resetDemo(): Promise<MemoryWorkspace>
}

