  background: linear-gradient(
    110deg,
    rgba(242, 239, 228, 0.06),
    rgba(242, 239, 228, 0.015)
  );
}
.reviewCopy {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.reviewCopy span {
  color: var(--text-dim);
  font: 500 8px/1 "Space Grotesk";
  letter-spacing: 0.1em;
}
.reviewCopy strong {
  font-size: 12px;
  font-weight: 500;
}
.reviewCopy p {
  margin: 0;
  color: var(--text-dim);
  font-size: 9px;
}
.reviewStack {
  position: relative;
  height: 70px;
}
.reviewStack i,
.reviewStack div {
  position: absolute;
  inset: 0;
  border: 1px solid var(--line);
  border-radius: 9px;
