  gap: 5px;
  padding: 12px 14px;
}
.reviewStack span,
.reviewStack small {
  color: var(--text-dim);
  font: 500 7.5px/1 "Space Grotesk";
}
.reviewStack b {
  font-size: 10px;
  font-weight: 500;
}
.feed {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
