  min-height: 30px;
  margin: 0;
  color: var(--text-dim);
  font-size: 9px;
  line-height: 1.65;
}
.changeCard ul {
  margin: 10px 0 0;
  padding-left: 14px;
  color: var(--text-soft);
  font-size: 8.5px;
  line-height: 1.7;
}
.cardActions {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 14px;
}
.acceptButton {
  display: inline-grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid #000;
  border-radius: 50%;
  color: #fff;
  background: #000;
  cursor: pointer;
  transition: transform 160ms var(--ease), background 160ms var(--ease);
}
.acceptButton:hover { transform: translateY(-1px); background: #202020; }
.acceptButton:focus-visible { outline: 2px solid var(--paper); outline-offset: 3px; }
.detailsButton {
  flex: 1;
