  align-items: center;
  gap: 6px;
  color: var(--text-soft);
  font-size: 9px;
}
.backdrop,
.cleanupBackdrop {
  position: fixed;
  z-index: 50;
  inset: 0 0 0 224px;
  display: grid;
  place-items: center;
  padding: 40px;
  background: rgba(4, 5, 6, 0.76);
  backdrop-filter: blur(16px);
}
.dialog {
  width: min(670px, 80vw);
  padding: 25px;
  border: 1px solid var(--line-strong);
  border-radius: 15px;
  background: #111317;
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.55);
}
.dialogTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--text-dim);
  font: 500 8px/1 "Space Grotesk";
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.dialogTop button {
  border: 0;
  color: var(--text-dim);
  background: transparent;
  cursor: pointer;
}
.dialog h2 {
  margin: 17px 0 20px;
  font-size: 19px;
  font-weight: 400;
  line-height: 1.45;
}
