  letter-spacing: 0.12em;
}
.cleanupCard h2 {
  margin: 30px 0 10px;
  font-size: 18px;
  font-weight: 400;
  line-height: 1.5;
}
.cleanupCard p {
  color: var(--text-dim);
  font-size: 9px;
  line-height: 1.7;
}
.cleanupCard > div {
  display: flex;
  gap: 8px;
  margin-top: auto;
}
.cleanupCard button {
  flex: 1;
}

/* Clarity refresh: one primary decision, readable at presentation distance. */
.summaryBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-top: 30px;
  padding: 18px 20px;
  border: 1px solid var(--glass-border);
  border-radius: 16px;
  background: var(--glass-surface);
  box-shadow: var(--glass-highlight), 0 18px 48px rgba(0, 0, 0, 0.18);
  backdrop-filter: blur(22px) saturate(125%);
}
.summaryBar div { display: flex; flex-direction: column; gap: 7px; }
.summaryBar span { color: var(--text); font-size: 14px; font-weight: 500; }
.summaryBar strong { color: var(--text-dim); font-size: 12px; font-weight: 400; }
.sectionHead { margin-top: 28px; }
.sectionHead span, .sectionHead b, .sectionHead button { font-size: 11px; }
.feed { grid-template-columns: 1fr; gap: 14px; }
.changeCard {
  min-height: auto;
  padding: 24px 26px;
  border-color: var(--glass-border);
  border-radius: 18px;
  background: var(--glass-surface);
  box-shadow: var(--glass-highlight), var(--glass-shadow);
  backdrop-filter: blur(22px) saturate(125%);
}
.cardMeta { font-size: 10px; }
.changeCard h2 { margin: 12px 0 0; font-size: 20px; line-height: 1.4; }
.changeCard > p { min-height: 0; margin: 10px 0 0; color: var(--text-soft); font-size: 14px; line-height: 1.7; }
.changeCard ul { color: var(--text-dim); font-size: 12px; line-height: 1.65; }
.cardActions { margin-top: 20px; }
.done { font-size: 13px; }
.disclosure {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  min-height: 48px;
  margin-top: 14px;
  border: 1px solid var(--line-strong);
  border-radius: 14px;
  color: var(--text-soft);
  background: rgba(255, 255, 255, 0.025);
  font-size: 13px;
  cursor: pointer;
}
.disclosure:hover { color: var(--text); background: rgba(255, 255, 255, 0.05); }
.dialog, .cleanupCard {
  border-color: var(--glass-border);
  background: var(--glass-surface-strong);
  box-shadow: var(--glass-highlight), 0 36px 100px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(24px) saturate(125%);
}
.dialogTop { font-size: 11px; }
.dialog h2 { font-size: 28px; }
.dialog > p, .diff p, .cleanupCard p { font-size: 14px; line-height: 1.7; }
.evidence { font-size: 12px !important; }
.dialogEvidence { margin: 14px 0 0; padding: 14px 16px 14px 34px; border: 1px solid var(--line); border-radius: 10px; color: var(--text-soft); background: rgba(255,255,255,.025); font-size: 13px; line-height: 1.7; }

@media (max-height: 760px) {
  .summaryBar { margin-top: 18px; padding: 13px 16px; }
  .sectionHead { margin-top: 18px; }
  .changeCard { padding: 18px 20px; }
  .changeCard h2 { font-size: 18px; }
  .disclosure { min-height: 42px; }
}

