import { expect, test } from '@playwright/test'

test('the complete Memory OS demo path stays interactive', async ({ page }) => {
  await page.goto('/#/home')
  await expect(page).toHaveTitle('Memory OS')
  await expect(page.locator('html')).toHaveAttribute('lang', 'ko')
  await expect(page.getByRole('heading', { name: '지금 당신은 이렇게 생겼습니다' })).toBeVisible()
  await page.getByRole('button', { name: '작년의 나와 뭐가 달라?' }).click()
  await expect(page.getByText(/스택 고착이 사라졌고/)).toBeVisible()

  await page.getByRole('link', { name: /Changes/ }).click()
  await page.getByRole('button', { name: '변경 내용 보기' }).click()
  await page.getByRole('button', { name: '이 이해를 승인' }).click()
  await expect(page.getByText('기억을 업데이트했습니다.')).toBeVisible()

  await page.getByRole('link', { name: /Memory/ }).click()
  const pin = page.getByRole('button', { name: '창업은 B2C 위주로 하고 싶음 고정' })
  await pin.click()
  await expect(pin).toHaveAttribute('aria-pressed', 'true')

  await page.getByRole('link', { name: /Chat/ }).click()
  await page.getByPlaceholder('메시지를 입력하세요').fill('나 요즘 Flutter 잘 안 쓰는데')
  await page.getByRole('button', { name: '메시지 보내기' }).click()
  await page.getByRole('button', { name: '모든 대화에 반영' }).click()
  await expect(page.getByText('모든 대화에 반영했습니다.')).toBeVisible()
})

test('all selected design views render at the reference viewport', async ({ page }) => {
  const views = [
    ['home', '/#/home', '지금 당신은 이렇게 생겼습니다'],
    ['changes', '/#/changes', '이번 주, AI가 당신에 대해 이해한 것이 이렇게 달라졌습니다.'],
    ['half-life', '/#/memory/half-life', '612개 중 어떤 것이 식어가고 있는가'],
    ['constellation', '/#/memory/constellation', '당신은 네 개의 덩어리로 이루어져 있습니다'],
    ['manual', '/#/memory/manual', '제가 지금 알고 있는 당신'],
    ['chat', '/#/chat', '대화하면서, 기억을 바로잡으세요'],
  ] as const

  for (const [name, route, heading] of views) {
    await page.goto(route)
    await expect(page.getByRole('heading', { name: heading })).toBeVisible()
    await page.screenshot({ path: `test-results/visual/${name}-1440x900.png`, fullPage: true })
  }
})

test('desktop minimum viewport does not introduce horizontal overflow', async ({ page }) => {
  await page.setViewportSize({ width: 1280, height: 720 })
  for (const [name, route] of [['home', '/#/home'], ['changes', '/#/changes'], ['half-life', '/#/memory/half-life'], ['constellation', '/#/memory/constellation'], ['manual', '/#/memory/manual'], ['chat', '/#/chat']] as const) {
    await page.goto(route)
    await expect.poll(() => page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true)
    await page.screenshot({ path: `test-results/visual/${name}-1280x720.png`, fullPage: true })
  }

  for (const route of ['/#/memory/half-life', '/#/memory/constellation']) {
    await page.goto(route)
    await expect.poll(() => page.locator('main > section').evaluate((element) => element.scrollHeight <= element.clientHeight + 1)).toBe(true)
  }
})

test('primary content uses presentation-readable type and selective glass', async ({ page }) => {
  await page.goto('/#/changes')
  const card = page.locator('article').first()
  await expect(card).toBeVisible()

  const styles = await card.evaluate((element) => {
    const paragraph = element.querySelector('p')
    const computed = getComputedStyle(element)
    return {
      bodySize: paragraph ? Number.parseFloat(getComputedStyle(paragraph).fontSize) : 0,
      backdrop: computed.backdropFilter,
    }
  })

  expect(styles.bodySize).toBeGreaterThanOrEqual(13)
  expect(styles.backdrop).toContain('blur')
})

test('every menu and previously decorative action has a real result', async ({ page }) => {
  await page.goto('/#/home')
  for (const [menu, route] of [['Changes', '/changes'], ['Memory', '/memory/half-life'], ['Chat', '/chat'], ['Access', '/access'], ['Settings', '/settings']] as const) {
    await page.getByRole('link', { name: new RegExp(menu) }).click()
    await expect(page).toHaveURL(new RegExp(`#${route.replaceAll('/', '\\/')}$`))
  }

  const downloadPromise = page.waitForEvent('download')
  await page.getByRole('button', { name: '내보내기' }).click()
  const download = await downloadPromise
  expect(download.suggestedFilename()).toBe('memory-os-export.json')

  await page.getByRole('button', { name: '열기', exact: true }).click()
  await expect(page.getByRole('heading', { name: '전체 기억 612개' })).toBeVisible()
  await expect(page.getByText('커피는 디카페인으로 마심')).toBeVisible()
})

