import { Check, GitBranch, Pin, Sparkles } from '../icons'
import { useState, type CSSProperties } from 'react'
import { NavLink, Navigate, useNavigate, useParams } from 'react-router-dom'
import type { MemoryCategory } from '../domain/memory'
import { useMemory } from '../state/MemoryContext'
import screen from './Screen.module.css'
import styles from './MemoryPage.module.css'
import { getClusterPoint } from './clusterLayout'

const validLenses = ['half-life', 'constellation', 'manual']

export function MemoryPage() {
  const { lens } = useParams()
  if (!lens || !validLenses.includes(lens)) return <Navigate to="/memory/half-life" replace />
  return <section className={screen.screen}><div className={screen.inner}>
    <div className={screen.topRow}><nav className={`${screen.tabs} ${styles.lensTabs}`} aria-label="기억 렌즈"><NavLink to="/memory/half-life">시간 흐름</NavLink><NavLink to="/memory/constellation">기억 관계</NavLink><NavLink to="/memory/manual">사용자 설명</NavLink></nav></div>
    {lens === 'half-life' && <HalfLife />}{lens === 'constellation' && <Constellation />}{lens === 'manual' && <Manual />}
  </div></section>
}

function HalfLife() {
  const { workspace, setPinned } = useMemory()
  const navigate = useNavigate()
  const [kept, setKept] = useState(false)
  const [selectedCategory, setSelectedCategory] = useState<MemoryCategory>('코딩')
  const buckets = ['archive', '1y', '90d', '30d', 'now'] as const
  const labels = ['보관 예정', '1년 전', '90일 전', '30일 전', '최근']
  const categories: MemoryCategory[] = ['코딩', '일', '취향', '개인']
  return <div className={styles.halfLife}>
    <div className={styles.lensHeading}><div><h1>612개 중 어떤 것이 식어가고 있는가</h1><p>기억은 지우는 게 아니라 시간이 지나면 옅어집니다. 붙잡고 싶은 것만 핀을 꽂으세요.</p></div><div className={styles.archiveCount}><b>18</b><span>7일 내 자동 보관 예정</span></div></div>
    <div className={styles.categoryTabs} aria-label="기억 분야">
      {categories.map((category) => <button key={category} type="button" aria-pressed={selectedCategory === category} onClick={() => setSelectedCategory(category)}>{category}</button>)}
    </div>
    <div className={styles.timelineHead}><span />{labels.map((label) => <b key={label}>{label}</b>)}</div>
    <div className={styles.timelineLine} />
    <div className={styles.memoryGrid}>
      <div className={styles.memoryRow}><strong>{selectedCategory}</strong>{buckets.map((bucket) => <div key={bucket} className={styles.bucket}>{workspace.memories.filter((item) => item.category === selectedCategory && item.ageBucket === bucket).map((memory) => <button key={memory.id} className={`${styles.memoryChip} ${styles[memory.state]} ${memory.pinned ? styles.pinned : ''}`} aria-label={`${memory.text} 고정`} aria-pressed={memory.pinned} onClick={() => void setPinned(memory.id, !memory.pinned)} style={{ '--strength': memory.strength } as CSSProperties}><span>{memory.text}</span>{memory.pinned && <Pin size={10} fill="currentColor" />}</button>)}</div>)}</div>
    </div>
