  </div>
}

function Cluster({ className, name, count, words }: { className: string; name: string; count: string; words: string[] }) {
  return <div className={`${styles.cluster} ${className}`}><div className={styles.clusterHalo} />{words.map((word,index) => { const point = getClusterPoint(index); return <div key={word} className={styles.star} data-side={point.side} style={{ '--x': point.x, '--y': point.y, '--size': `${point.size}px` } as React.CSSProperties}><i /><span>{word}</span></div> })}<b>{name} · {count}</b></div>
}

